  const [salt, h] = String(stored).split(':');
  const actual = crypto.scryptSync(pw, salt, 64);
  const expected = Buffer.from(h, 'hex');
  return expected.length === actual.length && crypto.timingSafeEqual(expected, actual);
}

export function validDate(s) {
  return typeof s === 'string' && DATE_RE.test(s) && !Number.isNaN(Date.parse(s + 'T00:00:00Z'));
}

export function readBody(req, limit = 5 * 1024 * 1024) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (c) => {
      size += c.length;
      if (size > limit) {
        reject(new HttpError(413, 'payload_too_large', 'body too large'));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

export function sendJson(res, status, body) {
  if (body === undefined) {
    res.writeHead(status);
    res.end();
    return;
  }
  const data = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': Buffer.byteLength(data) });
  res.end(data);
}

export function sendError(res, status, code, message) {
  sendJson(res, status, { error: code, message });
}

// RFC 4180 CSV parsing/serialisation (written for this project).

// Returns [{ line, fields }] where line is the 1-based physical line the record starts on.
// Blank records are skipped.
export function parseCsv(text) {
  const s = String(text).replace(/^﻿/, '');
  const records = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let line = 1;
  let recLine = 1;
  let i = 0;
  const pushRow = () => {
    row.push(field);
    records.push({ line: recLine, fields: row });
    row = [];
    field = '';
  };
  while (i < s.length) {
    const c = s[i];
    if (inQuotes) {
      if (c === '"') {
        if (s[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i++;
        continue;
      }
      if (c === '\n') line++;
      field += c;
      i++;
      continue;
    }
    if (c === '"' && field === '') {
      inQuotes = true;
      i++;
      continue;
    }
    if (c === ',') {
      row.push(field);
      field = '';
      i++;
      continue;
    }
    if (c === '\r' || c === '\n') {
      if (c === '\r' && s[i + 1] === '\n') i++;
      pushRow();
      line++;
      recLine = line;
      i++;
      continue;
    }
    field += c;
    i++;
  }
  if (inQuotes) throw new Error('unterminated quoted field');
  if (field !== '' || row.length > 0) pushRow();
  return records.filter((r) => !(r.fields.length === 1 && r.fields[0] === ''));
}

function escapeField(v) {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

export function toCsv(header, rows) {
  const lines = [header, ...rows].map((r) => r.map(escapeField).join(','));
  return lines.join('\r\n') + '\r\n';
}

import { ISSUE_TYPES, PRIORITIES } from './util.js';

// Tokenises the search query language. Throws Error on malformed input.
export function parseQuery(q) {
  const s = String(q);
  const n = s.length;
  const ws = (c) => /\s/.test(c);
  const terms = [];
  const readQuoted = (start) => {
    const end = s.indexOf('"', start + 1);
    if (end < 0) throw new Error('unterminated quoted phrase');
    return [s.slice(start + 1, end), end + 1];
  };
  let i = 0;
  while (i < n) {
    if (ws(s[i])) {
      i++;
      continue;
    }
    let neg = false;
    if (s[i] === '-' && i + 1 < n && !ws(s[i + 1])) {
      neg = true;
      i++;
    }
    if (s[i] === '"') {
      const [v, e] = readQuoted(i);
      if (!v.trim()) throw new Error('empty phrase');
      terms.push({ neg, field: null, value: v });
      i = e;
      continue;
    }
    let j = i;
    while (j < n && !ws(s[j]) && s[j] !== ':') j++;
    if (j < n && s[j] === ':') {
      const field = s.slice(i, j).toLowerCase();
      let value;
      let e;
      if (s[j + 1] === '"') {
        [value, e] = readQuoted(j + 1);
      } else {
        let k = j + 1;
        while (k < n && !ws(s[k])) k++;
        value = s.slice(j + 1, k);
        e = k;
      }
      if (!value) throw new Error(`empty value for ${field}`);
      terms.push({ neg, field, value });
      i = e;
      continue;
    }
    let k = i;
    while (k < n && !ws(s[k])) k++;
    terms.push({ neg, field: null, value: s.slice(i, k) });
    i = k;
  }
  return terms;
}

const cmp = (a, op, b) => {
  switch (op) {
    case '>': return a > b;
    case '<': return a < b;
    case '>=': return a >= b;
    case '<=': return a <= b;
    default: return a === b;
  }
};

// ctx: { user, isDone(issue), usernameOf(userId), activeSprintId(projectId) }
function compileOne(t) {
  const v = t.value;
  const lv = v.toLowerCase();
  if (t.field === null) {
    return (issue) => `${issue.title}\n${issue.description || ''}`.toLowerCase().includes(lv);
  }
  switch (t.field) {
    case 'status':
      return (i) => i.status.toLowerCase() === lv;
    case 'type':
      if (!ISSUE_TYPES.includes(lv)) throw new Error('invalid type');
      return (i) => i.type === lv;
    case 'priority':
      if (!PRIORITIES.includes(lv)) throw new Error('invalid priority');
      return (i) => i.priority === lv;
    case 'assignee':
      if (lv === 'me') return (i, c) => i.assigneeId === c.user.id;
      if (lv === 'none') return (i) => i.assigneeId == null;
      return (i, c) => (c.usernameOf(i.assigneeId) || '').toLowerCase() === lv;
    case 'label':
      return (i) => i.labels.some((l) => l.toLowerCase() === lv);
    case 'sprint':
      if (lv === 'active') return (i, c) => i.sprintId != null && c.activeSprintId(i.projectId) === i.sprintId;
      if (lv === 'none') return (i) => i.sprintId == null;
      return (i) => i.sprintId === v;
    case 'is':
      if (lv === 'open') return (i, c) => !c.isDone(i);
      if (lv === 'resolved') return (i, c) => c.isDone(i);
      throw new Error('is: must be open or resolved');
    case 'due': {
      const m = /^(<|>)?(\d{4}-\d{2}-\d{2})$/.exec(v);
      if (!m) throw new Error('invalid due date');
      const op = m[1] || '=';
      const d = m[2];
      return (i) => i.dueDate != null && cmp(i.dueDate, op, d);
    }
    case 'points': {
      const m = /^(>=|<=|>|<|=)?(\d+(?:\.\d+)?)$/.exec(v);
      if (!m) throw new Error('invalid points');
      const op = m[1] || '=';
      const num = Number(m[2]);
      return (i) => i.storyPoints != null && cmp(i.storyPoints, op, num);
    }
    case 'key': {
      if (!/^[A-Za-z]{2,10}-\d+$/.test(v)) throw new Error('invalid key');
      const ku = v.toUpperCase();
      return (i) => i.key === ku;
    }
    default:
      throw new Error(`unknown field: ${t.field}`);
  }
}

export function compileTerms(terms) {
  return terms.map((t) => {
    const p = compileOne(t);
    return t.neg ? (i, c) => !p(i, c) : p;
  });
}

