    const sort = query.get('sort') || 'updated';
    const cmpDesc = (a, b, f) => (a[f] < b[f] ? 1 : a[f] > b[f] ? -1 : 0);
    if (sort === 'updated') list.sort((a, b) => cmpDesc(a, b, 'updatedAt'));
    else if (sort === 'created') list.sort((a, b) => cmpDesc(a, b, 'createdAt'));
