      byType[i.type] = (byType[i.type] || 0) + 1;
      const a = usernameOf(i.assigneeId) || 'unassigned';
      byAssignee[a] = (byAssignee[a] || 0) + 1;
    }
    const cycles = [];
    for (const i of issues) {
