.card a { color: #1d2330; text-decoration: none; font-weight: 600; }
.badge { display: inline-block; padding: 1px 6px; border-radius: 10px; background: #dfe6f7; font-size: 0.75em; margin-right: 4px; }
.prio-urgent { background: #f8d7da; } .prio-high { background: #fde2c4; }
table { border-collapse: collapse; width: 100%; background: #fff; }
th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid #eceff5; font-size: 0.95em; vertical-align: top; }
